    [1684, t('Tefiya va Dionani kashf etdi','Открыл Тефию и Диону','Discovered Tethys and Dione')],
    [1712, t('14-sentabrda Parijda vafot etdi','14 сентября скончался в Париже','Died in Paris on 14 September')]
